import{_ as s,o as e,c as t,a0 as n}from"./chunks/framework.Cx-5KwGw.js";const u=JSON.parse('{"title":"GitHub和Gitee多账户","description":"","frontmatter":{"title":"GitHub和Gitee多账户","author":"麻瓜【码瓜】","date":"2024-07-07"},"headers":[],"relativePath":"posts/git/githubandgitee.md","filePath":"posts/git/githubandgitee.md"}'),i={name:"posts/git/githubandgitee.md"};function p(l,a,o,r,h,d){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="github和gitee多账户" tabindex="-1">GitHub和Gitee多账户 <a class="header-anchor" href="#github和gitee多账户" aria-label="Permalink to &quot;GitHub和Gitee多账户&quot;">​</a></h1><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><p>本文章主要是说明GitHub和Gitee多账号共存的问题</p><h2 id="全部相同" tabindex="-1">全部相同 <a class="header-anchor" href="#全部相同" aria-label="Permalink to &quot;全部相同&quot;">​</a></h2><p>用户名、邮箱都相同的情况下，可以公用一个id_rsa证书，证书的名称、存储的位置均为默认时，可以公用同一个证书。只需要把id_rsa.pub的内容分别填如GitHub和Gitee中即可。------&gt;已经过证实可以正常使用<br> 两个系统A/B，通过sftp下载A中的证书，再通过sftp上传到B中，可以迁移证书。------&gt;已经过证实可以正常使用</p><h2 id="部分相同" tabindex="-1">部分相同 <a class="header-anchor" href="#部分相同" aria-label="Permalink to &quot;部分相同&quot;">​</a></h2><h3 id="邮箱不同" tabindex="-1">邮箱不同 <a class="header-anchor" href="#邮箱不同" aria-label="Permalink to &quot;邮箱不同&quot;">​</a></h3><p>证书根据不同邮箱生成的，所以理论上必须生成不同的证书。</p><h3 id="用户名不同" tabindex="-1">用户名不同 <a class="header-anchor" href="#用户名不同" aria-label="Permalink to &quot;用户名不同&quot;">​</a></h3><p>在不同项目下配置项目级的user.name应该时可以使用。------&gt;推测，待验证</p><h3 id="不同证书" tabindex="-1">不同证书 <a class="header-anchor" href="#不同证书" aria-label="Permalink to &quot;不同证书&quot;">​</a></h3><p>待验证不同的情况<br> -证书名字不是默认的<br> -证书存储位置不是默认的<br> 证书存储位置默认，存储的名字不是默认的，在不更改其他配置下，无法正常使用。------&gt;已经过证实无法正常使用<br> 证书存储位置不是默认，存储名字是默认的，在不更改其他配置下，无法正常使用。------&gt;已经过证实无法正常使用</p><p>解决办法：在~/.ssh/下创建config文件，指定证书名称\\存储位置均可达到效果</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># GitHub</span></span>
<span class="line"><span>Host github.com</span></span>
<span class="line"><span>    HostName github.com</span></span>
<span class="line"><span>    User &lt;USER&gt;</span></span>
<span class="line"><span>    IdentityFile ~/.ssh/Github/id_rsa_github</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span># Gitee</span></span>
<span class="line"><span>host gitee.com</span></span>
<span class="line"><span>	Hostname gitee.com</span></span>
<span class="line"><span>	User &lt;USER&gt;</span></span>
<span class="line"><span>	IdentityFile ~/.ssh/Gitee/id_rsa_gitee</span></span></code></pre></div><p><strong><strong>特别注意</strong></strong><br> id_rsa文件的权限要改为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chmod 700 ./id_rsa</span></span></code></pre></div><p>否则会提示证书没有授权</p>`,17)])])}const b=s(i,[["render",p]]);export{u as __pageData,b as default};
